create or replace function public.guard_payment_request_transition() returns trigger language plpgsql security definer set search_path=public as $$ declare v_order public.orders; v_payment public.payments; v_outstanding numeric; begin if new.status in ('approved','completed','paid') then if new.related_payment_id is not null then select * into v_payment from public.payments where id=new.related_payment_id; if v_payment.id is null then raise exception 'Cannot approve payment request: related payment not found'; end if; end if; if new.reference is not null then select * into v_order from public.orders where payment_reference=new.reference limit 1; end if; if v_order.id is null and new.related_payment_id is not null then select * into v_payment from public.payments where id=new.related_payment_id; if v_payment.payment_reference is not null then select * into v_order from public.orders where payment_reference=v_payment.payment_reference limit 1; end if; end if; if v_order.id is null and new.type='property' then raise exception 'Cannot approve payment request: authoritative order not found'; end if; if v_order.id is not null then v_outstanding:=greatest(v_order.total_amount-coalesce(v_order.amount_paid,0),0); if coalesce(new.amount,0)<=0 or new.amount>v_outstanding+1 then raise exception 'Payment amount exceeds authoritative order balance'; end if; end if; end if; return new; end; $$;
